algorithm CountFailing
    define count as integer;
    define i as integer;
    define grade as integer;
    define failing as integer;
    read count;
    failing <- 0;
    for i <- 1 to count step 1 do
        read grade;
        if grade < 5 then
            failing <- failing + 1;
        endIf
    endFor
    write failing;
endAlgorithm

